'use strict';
// Админка: «База знаний (содержимое)»
/* ═════════════ Админка: «База знаний (содержимое)» ═════════════ */
function kbAdmTabs(){return [{id:'steps',label:'Шаги уроков',icon:'list'},{id:'shows',label:'Показы',icon:'play'},{id:'arts',label:'Статьи',icon:'book'},{id:'levels',label:'Уровни',icon:'grad'},{id:'news',label:'Новости',icon:'bell',count:NEWS.filter(n=>n.status==='Черновик').length||''}]}
function kbAdmAdd(){const t=S.tab||'steps';const io=k=>[{sep:true},{label:'Выгрузить в Excel',icon:'download',run:()=>exportDlg(k)},{label:'Загрузить из Excel',icon:'upload',run:()=>importDictDlg(k)}];
  if(t==='arts')return [{label:'Статья',icon:'book',run:()=>kbArtEditDlg()},...io('kbarts')];if(t==='news')return [{label:'Новость',icon:'bell',run:()=>newsEditDlg()},...io('kbnews')];if(t==='levels')return [];if(t==='shows')return [{label:'Показ для шага',icon:'play',run:()=>kbShowPick()},...io('kbshows')];return [{label:'Шаг урока',icon:'plus',run:()=>kbStepDlg()},...io('kbsteps')]}
const kbProg=i=>(KBG.find(g=>g.id===i.g)||{}).adm?'Администратор платформы':'Организации';
const kbPermTxt=i=>i.perm?permT(i.perm):(kbMod(i)?`Просмотр модуля «${kbModT(kbMod(i))}»`:'—');
function kbStepDlg(i0){const isNew=!i0;const i=i0||{g:'org',t:'',w:'',learn:1,star:0,perm:'',featk:'',evk:'open',active:true,mod:'org'};const featL=[['','—'],...FEATURES.map(f=>[f[0],f[1]])];
  openModal({form:true,size:'mid',render:()=>({title:isNew?'Новый шаг урока':'Шаг урока',sub:isNew?'Появится у всех с отметкой «Новое»':esc(i.t),body:`<div class="form">
    ${fld('Модуль программы',sel('ks-g',KBG.map(g=>[g.id,(g.adm?'Админка · ':'')+g.t]),i.g),{req:true,id:'ks-g'})}${fld('Вид шага',sel('ks-type',[['0','Сделать'],['1','Посмотреть']],i.learn?'1':'0'),{id:'ks-type',hint:'«Посмотреть» засчитывается, когда «Показать как» пройден до конца или статья шага дочитана'})}
    ${fld('Название',inp('ks-t',i.t),{req:true,full:true,id:'ks-t'})}${fld('Зачем это нужно',inp('ks-w',i.w||''),{full:true,id:'ks-w'})}
    ${fld('Статья',sel('ks-art',[['','— статья модуля'],...KB_ARTS.map(a=>[a.id,a.sec+' · '+a.t])],i.art||''),{id:'ks-art'})}${fld('Основной шаг «★»',`<label class="row" style="gap:8px"><input type="checkbox" class="sw" id="ks-star" ${i.star?'checked':''}>без него организация не может работать</label>`,{id:'ks-star'})}
    ${fld('Необходимое право',sel('ks-perm',[['','— просмотр модуля'],...PERMS.map(p=>[p[0],p[1]])],i.perm||''),{id:'ks-perm',hint:'Без этого права шаг не показывается и не входит в подсчёт'})}${fld('Функция учётной политики',sel('ks-feat',featL,i.featk||''),{id:'ks-feat',hint:'Если функция выключена, шаг скрыт'})}
    ${fld('Условие отметки',sel('ks-ev',Object.entries(KB_EV).map(([k,v])=>[k,v[0]]),i.evk),{id:'ks-ev',hint:'События задаёт разработчик'})}${fld('Место для «Перейти»',isNew?sel('ks-mod',[...BIZ,...ADM].filter((m,j,a)=>a.findIndex(x=>x.id===m.id)===j).map(m=>[m.id,m.title]),i.mod):`<span class="v">${esc(kbModT(kbMod(i))||'—')}${i.go&&i.go.tab?' → '+esc(i.go.tab):''}</span>`,{id:'ks-mod'})}
    ${fld('Показ «Показать как»',`<span class="v">${kbShowOf(i.id)?'Свой сценарий: '+kbShowN(kbShowOf(i.id))+' облачков':'Собирается автоматически по экрану шага'} · вкладка «Показы»</span>`,{full:true,id:'ks-how'})}
    ${fld('Активен',`<label class="row" style="gap:8px"><input type="checkbox" class="sw" id="ks-act" ${i.active!==false?'checked':''}>выключенный шаг пропадает из программ и из подсчёта</label>`,{id:'ks-act'})}</div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="ks-ok">Сохранить</button>',
    mount(el,m){$('#ks-ok',el).onclick=()=>{const t=val(el,'ks-t');if(!setErr(el,'ks-t',t?'':'Введите название'))return;
      const v={g:val(el,'ks-g'),t,w:val(el,'ks-w'),learn:val(el,'ks-type')==='1'?1:0,art:val(el,'ks-art')||'',star:$('#ks-star',el).checked?1:0,perm:val(el,'ks-perm'),featk:val(el,'ks-feat'),evk:val(el,'ks-ev'),active:$('#ks-act',el).checked};
      if(isNew){v.mod=val(el,'ks-mod');const o=born(Object.assign({id:'u'+Date.now().toString(36),isNew:true,ord:Math.max(0,...KBS.map(x=>x.ord))+1},v));if(o.featk)o.feat=null;kbBind(o);KBS.push(o);pdLog(`Шаги уроков: добавлен шаг «${t}» (${kbProg(o)})`,'steps')}
      else{const ch=[];if(i.t!==t)ch.push('название');if(i.active!==v.active)ch.push(v.active?'включён':'выключен');if(i.perm!==v.perm)ch.push('право');if(i.evk!==v.evk)ch.push('условие отметки');if(i.featk!==v.featk){ch.push('функция');i.feat=null}Object.assign(i,v);i.go=i.go||null;kbBind(i);touch(i);pdLog(`Шаги уроков: «${t}» изменён${ch.length?' — '+ch.join(', '):''}`,'steps')}
      KB.ver++;m.close();refreshAll();toast(isNew?'Шаг добавлен: появится у всех с отметкой «Новое»':'Шаг сохранён')}}})})}
function kbArtEditDlg(a0){const isNew=!a0;const a=a0||{sec:'Модули',t:'',mod:'',perm:'',aud:'biz',html:'',active:true};const secs=[...new Set(KB_ARTS.map(x=>x.sec))];
  openModal({form:true,size:'wide',render:()=>({title:isNew?'Новая статья':'Статья',sub:isNew?'':esc(a.t),body:`<div class="form">
    ${fld('Раздел',`<input class="inp" id="ka-sec" list="ka-secs" value="${esc(a.sec)}"><datalist id="ka-secs">${secs.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`,{req:true,id:'ka-sec'})}${fld('Название',inp('ka-t',a.t),{req:true,id:'ka-t'})}
    ${fld('К какому модулю относится',sel('ka-mod',[['','— общая статья'],...[...BIZ,...ADM].filter((m,j,l)=>l.findIndex(x=>x.id===m.id)===j).map(m=>[m.id,m.title])],a.mod||''),{id:'ka-mod',hint:'Эту статью открывает «?» в модуле'})}${fld('Право для просмотра',sel('ka-perm',[['','— у всех, кто видит модуль'],...PERMS.map(p=>[p[0],p[1]])],a.perm||''),{id:'ka-perm'})}
    ${fld('Кому',sel('ka-aud',[['biz','Организациям'],['adm','Администраторам платформы'],['all','Всем']],a.aud),{id:'ka-aud'})}${fld('Активна',`<label class="row" style="gap:8px"><input type="checkbox" class="sw" id="ka-act" ${a.active!==false?'checked':''}>показывается в «Базе знаний»</label>`,{id:'ka-act'})}
    ${fld('Текст',`<textarea class="inp" id="ka-html" style="min-height:240px;font-size:12.5px">${esc(a.html)}</textarea>`,{full:true,id:'ka-html',hint:'Разметка: абзацы, списки, заголовки, картинки'})}</div>
    <div class="row"><label class="btn sm" style="cursor:pointer">${ic('upload','sm')}Добавить картинку<input type="file" id="ka-img" accept="image/*" hidden></label><button class="btn sm ghost" id="ka-prev">${ic('eye','sm')}Предпросмотр</button></div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="ka-ok">Сохранить</button>',
    mount(el,m){$('#ka-img',el).onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)return toast('Картинка больше 2 МБ','alert',true);const rd=new FileReader();rd.onload=()=>{const ta=$('#ka-html',el);ta.value+=`\n<p><img src="${rd.result}" alt="${esc(f.name)}"></p>`;toast('Картинка добавлена в текст')};rd.readAsDataURL(f)};
      $('#ka-prev',el).onclick=()=>kbArtDlg({t:val(el,'ka-t')||'Без названия',sec:val(el,'ka-sec'),html:$('#ka-html',el).value});
      $('#ka-ok',el).onclick=()=>{const t=val(el,'ka-t'),sc=val(el,'ka-sec');if(![setErr(el,'ka-t',t?'':'Введите название'),setErr(el,'ka-sec',sc?'':'Укажите раздел')].every(Boolean))return;
        const v={sec:sc,t,mod:val(el,'ka-mod'),perm:val(el,'ka-perm'),aud:val(el,'ka-aud'),active:$('#ka-act',el).checked,html:$('#ka-html',el).value};
        if(isNew){const o=born(Object.assign({id:'a_u'+Date.now().toString(36)},v));KB_ARTS.push(o);pdLog(`Статьи: добавлена «${t}»`,'arts')}else{Object.assign(a,v);touch(a);pdLog(`Статьи: «${t}» изменена`,'arts')}
        KB.ver++;m.close();refreshAll();toast('Статья сохранена')}}})})}
function renderKbAdm(body,tab,fresh){const ioBar=k=>`<div class="row"><span class="muted">Выгрузка и загрузка через Excel: сопоставление по коду, перед применением — сравнение.</span><div class="grow"></div><button class="btn sm" data-exp="${k}">${ic('download','sm')}Выгрузить</button><button class="btn sm" data-imp="${k}">${ic('upload','sm')}Загрузить</button></div>`;
  body.onclick=e=>{const b=e.target.closest('[data-exp],[data-imp]');if(!b)return;b.dataset.exp?exportDlg(b.dataset.exp):importDictDlg(b.dataset.imp)};
  if(tab==='news')return renderNewsAdm(body,fresh,ioBar);
  if(tab==='arts'){body.innerHTML=`<div class="note">${ic('info')}<span>Статьи «Базы знаний» для всех организаций. Начальный набор — разделы «Инструкции пользователя Buhuchet.kg». Статьи о модулях, недоступных пользователю по правам, ему не показываются. Организации своих статей не добавляют.</span></div>${ioBar('kbarts')}<div id="pg"></div>${pdHistHtml('arts')}`;
    grid($('#pg',body),{id:'kb-arts',cols:[{key:'id',label:'Код',type:'text',w:90,val:a=>a.id,cls:'mono',hide:true},{key:'sec',label:'Раздел',type:'enum',w:170,val:a=>a.sec},{key:'t',label:'Название',type:'text',w:320,val:a=>a.t,html:a=>`<span class="strong">${esc(a.t)}</span>`},{key:'mod',label:'Модуль',type:'enum',w:200,val:a=>a.mod?kbModT(a.mod):'— общая'},{key:'perm',label:'Право для просмотра',type:'enum',w:200,val:a=>a.perm?permT(a.perm):'—'},{key:'aud',label:'Кому',type:'enum',w:170,val:a=>({biz:'Организациям',adm:'Администраторам',all:'Всем'})[a.aud]},{key:'len',label:'Объём, знаков',type:'int',w:120,num:true,hide:true,val:a=>stripTags(a.html).length},{key:'active',label:'Активна',type:'enum',w:100,val:a=>a.active!==false?'Да':'Нет'}],
      rows:()=>KB_ARTS,title:'t',noun:['статья','статьи','статей'],rowClass:a=>a.active!==false?'':'muted',open:a=>kbArtEditDlg(a),simulateLoad:fresh,
      actions:a=>[{label:'Изменить',icon:'edit',run:()=>kbArtEditDlg(a)},{label:'Предпросмотр',icon:'eye',run:()=>kbArtDlg(a)},{sep:true},a.active!==false?{label:'Отключить',icon:'ban',sub:'Статья пропадёт из «Базы знаний» организаций',run:()=>{a.active=false;touch(a);KB.ver++;pdLog(`Статьи: «${a.t}» отключена`,'arts');renderPage()}}:{label:'Включить',icon:'check',run:()=>{a.active=true;touch(a);KB.ver++;pdLog(`Статьи: «${a.t}» включена`,'arts');renderPage()}}]});return}
  if(tab==='shows'){body.innerHTML=`<div class="note">${ic('info')}<span>Сценарий «Показать как» для каждого шага. Без своего сценария показ собирается сам по экрану шага: заголовок, вкладки, «+ Добавить», плашки, список, столбцы, меню «…», поля формы. Свой сценарий задаёт порядок облачков и их тексты; тексты кнопок и полей для всех экранов — справочник «Тексты элементов» (kbUi). Невидимые пользователю элементы (нет права, выключена функция) показ пропускает.</span></div>${ioBar('kbshows')}<div id="pg"></div>${pdHistHtml('shows')}`;
    const sorted=()=>KBS.filter(i=>!(KBG.find(g=>g.id===i.g)||{}).adm).sort((a,b)=>(KBG.findIndex(g=>g.id===a.g)-KBG.findIndex(g=>g.id===b.g))||a.ord-b.ord);
    grid($('#pg',body),{id:'kb-shows',cols:[{key:'g',label:'Модуль программы',type:'enum',w:200,val:i=>(KBG.find(g=>g.id===i.g)||{}).t||''},{key:'t',label:'Шаг',type:'text',w:330,val:i=>i.t,html:i=>`<span class="strong">${esc(i.t)}</span>`},{key:'type',label:'Вид шага',type:'enum',w:120,val:i=>i.learn?'Посмотреть':'Сделать'},
      {key:'sc',label:'Сценарий',type:'enum',w:170,val:i=>kbShowOf(i.id)?'Свой':'Автоматический'},{key:'scr',label:'Экран',type:'text',w:160,val:i=>{const h=kbShowOf(i.id);return h&&h.scr||(typeof tScrOfStep==='function'?tScrOfStep(i)||'':'')}},{key:'n',label:'Облачков',type:'int',w:100,num:true,val:i=>{const h=kbShowOf(i.id);return h?kbShowN(h):0}},
      {key:'doit',label:'«Сделать сейчас»',type:'enum',w:180,val:i=>i.learn?'—':kbShowOf(i.id)&&kbShowOf(i.id).doit?'По сценарию':'Форма шага'},{key:'active',label:'Активен',type:'enum',w:100,val:i=>{const h=kbShowOf(i.id);return !h||h.active!==false?'Да':'Нет'}}],
      rows:sorted,title:'t',noun:['шаг','шага','шагов'],open:i=>kbShowDlg(i),simulateLoad:fresh,
      actions:i=>{const h=kbShowOf(i.id);return [{label:h?'Изменить сценарий':'Создать свой сценарий',icon:'edit',run:()=>kbShowDlg(i)},{label:'Предпросмотр',icon:'eye',run:()=>kbShowPrev(i)},...(h?[{sep:true},{label:'Вернуть автоматический',icon:'refresh',sub:'Свой сценарий удаляется',run:()=>{KBSH.splice(KBSH.indexOf(h),1);pdLog(`Показы: «${i.t}» — снова автоматический`,'shows');renderPage()}}]:[])]}});return}
  if(tab==='levels'){const box=(L,k,ttl)=>`<div class="box"><h3>${ttl}</h3><table class="mini"><thead><tr><th>№</th><th>Название уровня</th><th class="num">Порог, %</th></tr></thead><tbody>${L.map((l,j)=>`<tr><td>${j+1}</td><td><input class="inp" data-lvn="${k}|${j}" value="${esc(l.n)}" aria-label="Название уровня ${j+1}"></td><td class="num"><input class="inp num" style="max-width:90px" type="number" min="0" max="100" data-lvp="${k}|${j}" value="${l.p}" ${j===0?'disabled':''} aria-label="Порог уровня ${j+1}"></td></tr>`).join('')}</tbody></table><div class="row"><span class="grow hint">Первый уровень — всегда от 0 %; пороги растут сверху вниз, не больше 100 %.</span><button class="btn sm cta" data-lvsave="${k}">Сохранить</button></div><div class="red hint" data-lverr="${k}"></div></div>`;
    body.innerHTML=`<div class="note">${ic('info')}<span>Уровень даётся только по проценту выполненных шагов своей программы. Названия и пороги меняются для всех сразу; уже полученные уровни не отнимаются.</span></div>${box(KB_LVB,'b','Уровни пользователей организаций')}${box(KB_LVA,'a','Уровни администраторов платформы')}${pdHistHtml('levels')}`;
    body.onclick=e=>{const b=e.target.closest('[data-lvsave]');if(!b)return;const k=b.dataset.lvsave;const L=k==='b'?KB_LVB:KB_LVA;const ns=L.map((l,j)=>$(`[data-lvn="${k}|${j}"]`).value.trim()),ps=L.map((l,j)=>j?+$(`[data-lvp="${k}|${j}"]`).value:0);
      const err=ns.some(x=>!x)?'У каждого уровня должно быть название':ps.some((p,j)=>j&&(!(p>ps[j-1])||p>100))?'Пороги должны расти и быть не больше 100 %':'';$(`[data-lverr="${k}"]`).textContent=err;if(err)return;
      const ch=L.map((l,j)=>l.n!==ns[j]||l.p!==ps[j]?`${j+1}: ${l.n} ${l.p} % → ${ns[j]} ${ps[j]} %`:'').filter(Boolean);if(!ch.length)return toast('Изменений нет');L.forEach((l,j)=>{l.n=ns[j];l.p=ps[j]});KB.ver++;pdLog(`Уровни (${k==='b'?'организации':'администраторы'}): ${ch.join('; ')}`,'levels');renderPage();toast('Уровни сохранены: полученные уровни не отнимаются')};return}
  body.innerHTML=`<div class="note">${ic('info')}<span>Шаги программ обучения для всех организаций и отдельная программа для администраторов платформы. Шаг с действием показывается только тем, у кого есть его право; шаг «Посмотреть» — тем, кто видит модуль. Шаг «Сделать» засчитывается сохранённым действием, «Посмотреть» — 3 секундами на экране шага после «Перейти», показом «Показать как» до конца или дочитанной статьёй шага. Сценарии показов — вкладка «Показы». Новый шаг появляется у всех с отметкой «Новое», выключенный пропадает из программ и из подсчёта.</span></div>${ioBar('kbsteps')}<div id="pg"></div>${pdHistHtml('steps')}`;
  const sorted=()=>KBS.slice().sort((a,b)=>(KBG.findIndex(g=>g.id===a.g)-KBG.findIndex(g=>g.id===b.g))||a.ord-b.ord);
  grid($('#pg',body),{id:'kb-steps',cols:[{key:'n',label:'№',type:'int',w:60,num:true,val:i=>sorted().indexOf(i)+1},{key:'id',label:'Код',type:'text',w:90,val:i=>i.id,cls:'mono',hide:true},{key:'prog',label:'Программа',type:'enum',w:190,val:kbProg,hide:true},{key:'g',label:'Модуль программы',type:'enum',w:200,val:i=>(KBG.find(g=>g.id===i.g)||{}).t||''},
    {key:'t',label:'Название',type:'text',w:330,val:i=>i.t,html:i=>`${i.star?'<span class="ck-star">★</span> ':''}<span class="strong">${esc(i.t)}</span>${i.isNew?' <span class="pill sm blue">Новое</span>':''}`},{key:'type',label:'Вид шага',type:'enum',w:120,val:i=>i.learn?'Посмотреть':'Сделать'},{key:'star',label:'Основной',type:'enum',w:100,val:i=>i.star?'★':'—',hide:true},
    {key:'perm',label:'Необходимое право',type:'text',w:240,val:kbPermTxt},{key:'feat',label:'Функция учётной политики',type:'enum',w:200,hide:true,val:i=>i.featk?(FEATURES.find(f=>f[0]===i.featk)||[])[1]||'':'—'},{key:'evk',label:'Условие отметки',type:'enum',w:230,val:i=>(KB_EV[i.evk]||['—'])[0]},{key:'active',label:'Активен',type:'enum',w:100,val:i=>i.active!==false?'Да':'Нет'}],
    rows:sorted,title:'t',noun:['шаг','шага','шагов'],sort:{key:'n',dir:1},rowClass:i=>i.active!==false?'':'muted',open:i=>kbStepDlg(i),simulateLoad:fresh,
    actions:i=>{const sib=KBS.filter(x=>x.g===i.g).sort((a,b)=>a.ord-b.ord);const k=sib.indexOf(i);const mv=d=>{const o=sib[k+d];[i.ord,o.ord]=[o.ord,i.ord];KB.ver++;pdLog(`Шаги уроков: «${i.t}» перемещён ${d<0?'выше':'ниже'}`,'steps');renderPage()};
      return [{label:'Изменить',icon:'edit',run:()=>kbStepDlg(i)},{label:'Выше',icon:'up',disabled:k===0,run:()=>mv(-1)},{label:'Ниже',icon:'dn',disabled:k===sib.length-1,run:()=>mv(1)},{sep:true},i.active!==false?{label:'Выключить',icon:'ban',sub:'Шаг пропадёт из программ и из подсчёта',run:()=>{i.active=false;touch(i);KB.ver++;pdLog(`Шаги уроков: «${i.t}» выключен`,'steps');renderPage()}}:{label:'Включить',icon:'check',run:()=>{i.active=true;touch(i);KB.ver++;pdLog(`Шаги уроков: «${i.t}» включён`,'steps');renderPage()}}]}})}


/* ═════════════ Админка: «Показы» — сценарии «Показать как» ═════════════ */
const kbShowOf=id=>KBSH.find(x=>x.step===id)||null;
const kbShowN=h=>h.items.length;
const KB_AUTO={screen:'Все элементы экрана',grid:'Список: столбцы, фильтры, строка, меню «…»',add:'«+ Добавить» и пункты его меню',boxes:'Блоки экрана',plates:'Плашки',tabs:'Вкладки',fields:'Поля формы',card:'Карточка: вкладки, блоки, кнопки',form:'Форма: все поля',menu:'Меню действий: каждый пункт'};
// Описание пункта для администратора: что подсвечивается
function kbShowWhat(p){if(p.auto)return 'Автоматически: '+(KB_AUTO[p.auto]||p.auto)+(p.sub&&p.sub.some(a=>a&&a.tab)?' · вкладка «'+p.sub.find(a=>a&&a.tab).tab+'»':'');if(p.txt)return `Элемент с текстом «${p.txt}»`;if(p.s)return 'Элемент экрана';return 'Только текст'}
function kbShowPick(){const l=KBS.filter(i=>!(KBG.find(g=>g.id===i.g)||{}).adm&&!kbShowOf(i.id));if(!l.length)return toast('У всех шагов уже есть свой сценарий');
  openModal({form:true,size:'mid',render:()=>({title:'Свой сценарий показа',body:`<div class="form">${fld('Шаг',sel('sp-s',l.map(i=>[i.id,(KBG.find(g=>g.id===i.g)||{}).t+' · '+i.t])),{req:true,full:true,id:'sp-s'})}</div>`,foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="sp-ok">Далее</button>',
    mount(el,m){$('#sp-ok',el).onclick=()=>{const i=ckFind(val(el,'sp-s'))||KBS.find(x=>x.id===val(el,'sp-s'));m.close();kbShowDlg(i)}}})})}
function kbShowDlg(i){const h0=kbShowOf(i.id);const h=h0?JSON.parse(JSON.stringify(h0)):{id:'sh-'+i.id,step:i.id,active:true,items:[{auto:'screen'}]};
  openModal({form:true,size:'wide',render:()=>({title:'Сценарий показа',sub:esc(i.t),body:`<div class="note">${ic('info')}<span>Первое облачко — название шага и «Зачем это нужно», последнее — «Готово» или «Сделать сейчас»: их программа добавляет сама. Здесь — облачки между ними. Тексты можно менять; что подсвечивать, задаёт разработчик.</span></div>
    <div class="form">${fld('Активен',`<label class="row" style="gap:8px"><input type="checkbox" class="sw" id="sh-act" ${h.active!==false?'checked':''}>выключенный сценарий заменяется автоматическим</label>`,{id:'sh-act'})}</div>
    <div class="sh-list">${h.items.map((p,k)=>`<div class="box sh-it"><div class="row"><b class="grow">${k+1}. ${esc(kbShowWhat(p))}</b><button class="icon-btn sm" data-shup="${k}" ${k?'':'disabled'} aria-label="Выше">${ic('up','sm')}</button><button class="icon-btn sm" data-shdel="${k}" aria-label="Удалить">${ic('trash','sm')}</button></div>
      ${p.auto?'<span class="hint">Облачка и тексты берутся из справочника текстов элементов; общие элементы (поиск, «Столбцы», «На весь экран», кнопки формы) система отмечает сама</span>':`${fld('Заголовок облачка',`<input class="inp" data-sht="${k}" value="${esc(p.t||'')}">`,{full:true})}${fld('Текст облачка: что делает и пример',`<textarea class="inp" data-shx="${k}" style="min-height:60px">${esc(p.x||'')}</textarea>`,{full:true})}
      <label class="row sh-common"><input type="checkbox" data-shc="${k}" ${p.common?'checked':''}><span><b>Общий элемент</b><span class="hint" style="display:block;margin:0">Одинаковый на всех экранах: пройденное один раз облачко больше не показывается пользователю ни на одном экране</span></span></label>`}</div>`).join('')}</div>
    <div class="row"><button class="btn sm" id="sh-addt">${ic('plus','sm')}Облачко с текстом</button><button class="btn sm" id="sh-adda">${ic('plus','sm')}Все элементы экрана</button><div class="grow"></div><button class="btn sm ghost" id="sh-prev">${ic('eye','sm')}Предпросмотр</button></div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="sh-ok">Сохранить</button>',
    mount(el,m){const rd=()=>{$$('[data-sht]',el).forEach(x=>h.items[+x.dataset.sht].t=x.value);$$('[data-shx]',el).forEach(x=>h.items[+x.dataset.shx].x=x.value);$$('[data-shc]',el).forEach(x=>{const p=h.items[+x.dataset.shc];if(x.checked)p.common=true;else delete p.common})};
      el.querySelector('.mb').onclick=e=>{const b=e.target.closest('[data-shup],[data-shdel],#sh-addt,#sh-adda,#sh-prev');if(!b)return;rd();
        if(b.dataset.shup){const k=+b.dataset.shup;[h.items[k-1],h.items[k]]=[h.items[k],h.items[k-1]]}else if(b.dataset.shdel)h.items.splice(+b.dataset.shdel,1);else if(b.id==='sh-addt')h.items.push({t:'',x:''});else if(b.id==='sh-adda')h.items.push({auto:'screen'});else if(b.id==='sh-prev')return kbShowPrev(i,h);m.draw()};
      $('#sh-ok',el).onclick=()=>{rd();if(h.items.some(p=>!p.auto&&!(p.t||'').trim()))return toast('У каждого облачка должен быть заголовок','alert',true);h.active=$('#sh-act',el).checked;
        if(h0)Object.assign(h0,h);else KBSH.push(h);pdLog(`Показы: «${i.t}» — ${h0?'сценарий изменён':'создан свой сценарий'} (${h.items.length} облачков)`,'shows');m.close();renderPage();toast('Сценарий сохранён')}}})})}
// Предпросмотр для администратора: облачки по порядку (сам показ идёт на экране организации)
function kbShowPrev(i,h){h=h||kbShowOf(i.id)||{items:[{auto:'screen'}]};const L=[{t:i.t,x:i.w||''},...h.items.map(p=>p.auto?{t:'Автоматически',x:KB_AUTO[p.auto]||p.auto,a:1}:p),i.learn?{t:tq('finLookT'),x:tq('finLook')}:{t:tq('finDoT'),x:tq('finDo')}];
  openModal({size:'mid',render:()=>({title:'Предпросмотр показа',sub:esc(i.t),body:`<ol class="sh-prev">${L.map(p=>`<li><b>${esc(p.t||'')}</b>${p.a?' <span class="tag">авто</span>':''}${p.common?' <span class="tag">общий элемент</span>':''}<p>${esc(p.x||'')}</p></li>`).join('')}</ol><p class="hint" style="margin:0">Облачки «Автоматически» раскрываются по живому экрану: по одному на каждую вкладку, кнопку, столбец, пункт меню или поле.</p>`,foot:'<button class="btn cta" data-close>Закрыть</button>'})})}
